package forth

import (
	"errors"
	"strconv"
	"strings"
)

var (
	errEmptyStack   = errors.New("empty stack")
	errOneValue     = errors.New("only one value on the stack")
	errDivideByZero = errors.New("divide by zero")
	errUndefined    = errors.New("undefined operation")
	errIllegal      = errors.New("illegal operation")
)

type definition struct {
	body  []string
	scope map[string]*definition
}

type forthVM struct {
	stack []int
	words map[string]*definition
}

type builtin func(*forthVM) error

var builtins = map[string]builtin{
	"+":    arith(func(a, b int) int { return a + b }),
	"-":    arith(func(a, b int) int { return a - b }),
	"*":    arith(func(a, b int) int { return a * b }),
	"/":    divide,
	"dup":  dup,
	"drop": drop,
	"swap": swap,
	"over": over,
}

func arith(op func(a, b int) int) builtin {
	return func(f *forthVM) error {
		a, b, ok := f.pop2()
		if !ok {
			return errEmptyStack
		}
		f.stack = append(f.stack, op(a, b))
		return nil
	}
}

func divide(f *forthVM) error {
	a, b, ok := f.pop2()
	if !ok {
		return errEmptyStack
	}
	if b == 0 {
		return errDivideByZero
	}
	f.stack = append(f.stack, a/b)
	return nil
}

func dup(f *forthVM) error {
	if len(f.stack) < 1 {
		return errEmptyStack
	}
	top := f.stack[len(f.stack)-1]
	f.stack = append(f.stack, top)
	return nil
}

func drop(f *forthVM) error {
	if len(f.stack) < 1 {
		return errEmptyStack
	}
	f.stack = f.stack[:len(f.stack)-1]
	return nil
}

func swap(f *forthVM) error {
	if len(f.stack) < 2 {
		return errEmptyStack
	}
	n := len(f.stack)
	f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
	return nil
}

func over(f *forthVM) error {
	if len(f.stack) < 2 {
		return errEmptyStack
	}
	f.stack = append(f.stack, f.stack[len(f.stack)-2])
	return nil
}

func (f *forthVM) pop2() (a, b int, ok bool) {
	if len(f.stack) < 2 {
		return 0, 0, false
	}
	n := len(f.stack)
	return f.stack[n-2], f.stack[n-1], true
}

func (f *forthVM) pop1() (int, error) {
	if len(f.stack) < 1 {
		return 0, errEmptyStack
	}
	n := len(f.stack)
	v := f.stack[n-1]
	f.stack = f.stack[:n-1]
	return v, nil
}

func (f *forthVM) push(v int) {
	f.stack = append(f.stack, v)
}

func (f *forthVM) runToken(tok string) error {
	if n, ok := parseNumber(tok); ok {
		f.push(n)
		return nil
	}
	name := strings.ToLower(tok)
	if d, ok := f.words[name]; ok {
		return f.exec(d)
	}
	if b, ok := builtins[name]; ok {
		return b(f)
	}
	return errUndefined
}

func (f *forthVM) exec(d *definition) error {
	for _, tok := range d.body {
		if n, ok := parseNumber(tok); ok {
			f.push(n)
			continue
		}
		name := strings.ToLower(tok)
		if sub, ok := d.scope[name]; ok {
			if err := f.exec(sub); err != nil {
				return err
			}
			continue
		}
		if b, ok := builtins[name]; ok {
			if err := b(f); err != nil {
				return err
			}
			continue
		}
		return errUndefined
	}
	return nil
}

func parseNumber(tok string) (int, bool) {
	if tok == "" {
		return 0, false
	}
	s := tok
	neg := false
	if s[0] == '-' {
		neg = true
		s = s[1:]
	}
	if s == "" {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, false
	}
	if neg {
		n = -n
	}
	return n, true
}

func Forth(input []string) ([]int, error) {
	f := &forthVM{
		stack: []int{},
		words: map[string]*definition{},
	}
	defining := false
	var def *definition
	var defName string
	for _, line := range input {
		for _, tok := range strings.Fields(line) {
			if defining {
				switch {
				case tok == ";":
					if defName == "" {
						return nil, errIllegal
					}
					f.words[defName] = def
					defining = false
					def = nil
					defName = ""
				case defName == "":
					if _, ok := parseNumber(tok); ok {
						return nil, errIllegal
					}
					defName = strings.ToLower(tok)
				default:
					def.body = append(def.body, tok)
				}
				continue
			}
			if tok == ":" {
				defining = true
				scope := make(map[string]*definition, len(f.words))
				for k, v := range f.words {
					scope[k] = v
				}
				def = &definition{scope: scope}
				defName = ""
				continue
			}
			if err := f.runToken(tok); err != nil {
				return nil, err
			}
		}
	}
	if defining {
		return nil, errIllegal
	}
	return f.stack, nil
}

